@RestController
@RequestMapping("/api/users")
public class UserController {

    private final UserRepository userRepository;

    public UserController(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    @GetMapping("/{userId}")
    public User getUserById(@PathVariable Long userId) {
        // Spring extracts userId from /api/users/42 -> userId = 42
        return userRepository.findById(userId)
            .orElseThrow(() -> new ResourceNotFoundException("User not found"));
    }

    @GetMapping("/{userId}/orders/{orderId}")
    public Order getUserOrder(@PathVariable Long userId, 
                              @PathVariable Long orderId) {
        // Multiple path variables: /api/users/10/orders/250
        return userRepository.findOrderByUserAndId(userId, orderId)
            .orElseThrow(() -> new ResourceNotFoundException("Order not found"));
    }
}

@RestController
@RequestMapping("/api/users")
public class UserController {

    private final UserRepository userRepository;

    public UserController(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    @GetMapping
    public List<User> searchUsers(
            @RequestParam(required = false) String status,
            @RequestParam(required = false) String email,
            @RequestParam(defaultValue = "0") int page,
            @RequestParam(defaultValue = "20") int size) {
        // GET /api/users?status=ACTIVE&page=2&size=10
        // status and email are optional (null if not provided)
        // page defaults to 0, size defaults to 20
        return userRepository.findUsers(status, email, page, size);
    }

    @GetMapping("/search")
    public List<User> searchByName(
            @RequestParam String name,  // required: returns 400 if missing
            @RequestParam(defaultValue = "ASC") String sortOrder) {
        return userRepository.findByNameContaining(name, sortOrder);
    }
}

