@RestController
@RequestMapping("/users")
class UserController {

    // PATH VARIABLE — identifies WHICH resource: GET /users/42
    @GetMapping("/{id}")
    public User getById(@PathVariable Long id) {
        return userService.findById(id);
    }

    // REQUEST PARAM — filters/options: GET /users?status=ACTIVE&page=0
    @GetMapping
    public List<User> search(@RequestParam String status,
                             @RequestParam(defaultValue = "0") int page) {
        return userService.findByStatus(status, page);
    }
}
