@RestController
@RequestMapping("/api/products")
public class ProductController {

    private final ProductRepository productRepository;

    public ProductController(ProductRepository productRepository) {
        this.productRepository = productRepository;
    }

    @GetMapping
    public List<Product> searchProducts(
            @RequestParam(required = false) String category,
            @RequestParam(required = false) String name,
            @RequestParam(defaultValue = "0") int page,
            @RequestParam(defaultValue = "20") int size,
            @RequestParam(defaultValue = "name") String sortBy) {
        // All these work:
        // GET /api/products -> defaults: page=0, size=20, sortBy=name, category=null, name=null
        // GET /api/products?category=electronics
        // GET /api/products?page=2&size=10&sortBy=price
        return productRepository.findProducts(category, name, page, size, sortBy);
    }
}

@RestController
@RequestMapping("/api/products")
public class ProductController {
    private final ProductService productService;

    @GetMapping
    public List<Product> getProducts(
            @RequestParam(required = false) List<String> categories,
            @RequestParam(required = false) List<Long> ids) {
        if (ids != null && !ids.isEmpty()) {
            return productService.findByIds(ids); // batch fetch
        }
        if (categories != null && !categories.isEmpty()) {
            return productService.findByCategories(categories); // multi-filter
        }
        return productService.findAll();
    }

    @DeleteMapping("/batch")
    public void deleteProducts(@RequestParam List<Long> ids) {
        productService.deleteByIds(ids); // bulk delete
    }

    @GetMapping("/tags")
    public List<Product> getByTags(@RequestParam("tag") String[] tags) {
        return productService.findByTags(List.of(tags)); // array alternative
    }

    @GetMapping("/unique-categories")
    public List<Product> getByUniqueCategories(@RequestParam Set<String> categories) {
        return productService.findByCategories(categories); // Set removes duplicates
    }
}

@RestController
@RequestMapping("/api/users")
public class UserController {
    private final UserService userService;

    @GetMapping
    public List<User> getAllUsers() {
        return userService.findAll();
    }

    @GetMapping("/{userId}")
    public User getUserById(@PathVariable Long userId) {
        return userService.findById(userId).orElseThrow();
    }

    @PostMapping
    public User createUser(@RequestBody User user) {
        return userService.save(user);
    }

    @PutMapping("/{userId}")
    public User updateUser(@PathVariable Long userId, @RequestBody User user) {
        return userService.update(userId, user);
    }

    @DeleteMapping("/{userId}")
    public void deleteUser(@PathVariable Long userId) {
        userService.delete(userId);
    }

    @GetMapping("/{userId}/orders")
    public List<Order> getUserOrders(@PathVariable Long userId) {
        return userService.findOrdersByUserId(userId); // nested resource
    }

    @GetMapping("/{userId}/orders/{orderId}")
    public Order getUserOrder(@PathVariable Long userId, @PathVariable Long orderId) {
        return userService.findOrder(userId, orderId); // two-level hierarchy
    }
}
